    before_schema, after_schema = before["schema"], after["schema"]
    result = {
        "dataset": dataset,
        "left": left,
        "right": right,
        "addedFields": sorted(after_schema.keys() - before_schema.keys()),
        "removedFields": sorted(before_schema.keys() - after_schema.keys()),
